{
  "technical_and_design_decisions": [
    "U1: Design Java/Node.js contract API model to create thread-safe contract instances or context wrappers per transaction, ensuring transaction stub isolation without significant performance overhead.",
    "U2/U3: Move proto helper functions from 'protos/utils' to a new standalone 'protoutils' package, updating all import references across the repository.",
    "U4: Backport Kafka health check handlers and metrics from the master branch into the 1.4 LTS release branch, maintaining backward compatibility with 1.4 dependencies.",
    "U5: Enhance the peer endorsement and ACL evaluation logic to permit channel Readers to execute read-only chaincode invocations (queries) that do not generate write sets.",
    "U6: Introduce a dedicated configuration setting 'peer.discovery.externalEndpoint' to explicitly set the peer address advertised via Service Discovery independently of the internal gossip bind address.",
    "U7: Register a REST '/version' endpoint on the operations service HTTP server for both peer and orderer binaries to expose version, commit hash, and build metadata.",
    "U8: Audit and refactor Go chaincode samples to adhere strictly to idiomatic Go design patterns, error handling conventions, and clean code principles."
  ],
  "assumptions": [
    "The work will be executed by a single developer with experience in Go, Java, Docker, and Hyperledger Fabric architecture.",
    "User stories U2 and U3 represent identical specifications for refactoring 'protos/utils' and will be handled as a single unified effort.",
    "Existing CI/CD pipelines and integration test harnesses are available for local and automated testing.",
    "Effort is estimated in standard 8-hour developer workdays."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Contract Transaction Context Implementation (U1)",
      "activity_description": "Implement transactional context access for contract methods, including thread-safe instance-per-transaction lifecycle handling in Java/Node contract APIs and writing unit tests.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Proto Package Cleanup & Refactoring (U2/U3)",
      "activity_description": "Extract protos/utils into the new protoutils package, update import references across core modules, clean up obsolete packages, and verify build scripts.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Kafka Health Check Backport to 1.4 LTS (U4)",
      "activity_description": "Port Kafka health checker logic and endpoints from master to the v1.4 branch, adapt for dependency differences, and add regression tests.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Channel Reader Query ACL & Execution Support (U5)",
      "activity_description": "Update access control policy enforcement on peer proposal handlers to allow Channel Readers to execute read-only chaincode proposals, preventing write-set modifications.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Service Discovery External Endpoint Config (U6)",
      "activity_description": "Add new peer configuration parameters for service discovery external endpoint override, update discovery service advertisement logic, and write tests.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Operations Service Version Endpoint (U7)",
      "activity_description": "Add the /version REST endpoint to the operations service package in both peer and orderer binaries, exposing version and build metadata.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Idiomatic Golang Samples Refactoring (U8)",
      "activity_description": "Review and refactor Go chaincode samples to use idiomatic Go syntax, standard error checks, and modern packaging practices.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Integration Testing & Regression Suite Execution",
      "activity_description": "Execute end-to-end network tests, integration tests across peer/orderer services, and verify all updates against existing Fabric sample scenarios.",
      "most_likely_effort": 3.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 21.0
  }
}

